Translate the following MS C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
using namespace std;

int computeGCD(int a, int b) {
    while (b != 0) {
        int temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

int main() {
    int x_input, y_input, limit_input;
    cin >> x_input >> y_input >> limit_input;
    double ratio_target = (double)x_input / y_input;
    double min_diff = 1e9;
    int final_num = 0, final_den = 1;

    for (int i = 1; i <= limit_input; ++i) {
        int b_value = (long long)x_input * i / y_input;
        double candidates[] = {
            (double)b_value / i,
            (double)(abs(b_value - 1)) / i,
            (double)(b_value + 1) / i
        };
        int candidate_nums[] = {b_value, abs(b_value - 1), b_value + 1};

        for (int j = 0; j < 3; ++j) {
            double diff = fabs(ratio_target - candidates[j]);
            if (diff < min_diff) {
                min_diff = diff;
                final_num = candidate_nums[j];
                final_den = i;
            }
        }
    }

    if (fabs(1.0 - ratio_target) <= (fabs((double)final_num / final_den) - ratio_target) + 1e-9) {
        final_num = 1;
        final_den = 1;
    }

    int gcd_value = computeGCD(final_num, final_den);
    cout << final_num / gcd_value << "/" << final_den / gcd_value << endl;
    return 0;
}
